//! The typescript generator. Written against spec/client.md.

use crate::names::{Escape, flatten, lower_camel, metric_doc, quote, upper_camel};
use std::fmt::Write;
use trail_core::decl::{Base, Declarations, EventDecl, MetricDecl, PropType};

/// The type names the generated file imports. An event's props type may not take one.
pub const IMPORTED: [&str; 3] = ["EmitContext", "JsonValue", "TrailClient"];

/// An event or metric's method name: `shop.order.placed` → `shopOrderPlaced`. Any identifier,
/// keywords included, is a valid method name in an object literal.
pub fn method(name: &str) -> String {
    lower_camel(name)
}

/// An event's props type: `shop.order.placed` → `ShopOrderPlaced`.
pub fn props_type(name: &str) -> String {
    upper_camel(name)
}

fn doc(text: &str) -> String {
    format!("/** {} */", flatten(text).replace("*/", "*\\/"))
}

pub fn type_of(prop: &PropType) -> String {
    match &prop.base {
        Base::String => "string".to_string(),
        Base::Int | Base::Float => "number".to_string(),
        Base::Bool => "boolean".to_string(),
        Base::StringList => "string[]".to_string(),
        Base::Json => "JsonValue".to_string(),
        Base::Enum(values) => {
            let values: Vec<String> = values.iter().map(|v| quote(v, Escape::TypeScript)).collect();
            values.join(" | ")
        }
    }
}

pub fn generate(decl: &Declarations) -> String {
    let source = &decl.source;
    let has_json = decl
        .events
        .values()
        .flat_map(|event| event.props.values())
        .any(|prop| prop.base == Base::Json);
    let imports: Vec<&str> = [
        ("EmitContext", !decl.events.is_empty()),
        ("JsonValue", has_json),
        ("TrailClient", true),
    ]
    .into_iter()
    .filter_map(|(name, used)| used.then_some(name))
    .collect();

    let mut out = String::new();
    let _ = writeln!(
        out,
        "// Generated by `trail gen` from the declarations of `{source}`. Do not edit."
    );
    out.push_str("// Change the TOML files and run `trail gen` again.\n");
    let _ = writeln!(
        out,
        "import type {{ {} }} from \"trail-client\";",
        imports.join(", ")
    );
    let _ = writeln!(
        out,
        "\nexport const SOURCE = {};",
        quote(source, Escape::TypeScript)
    );

    for (name, event) in &decl.events {
        out.push('\n');
        push_props_type(&mut out, name, event);
    }

    out.push('\n');
    let _ = writeln!(out, "/** Typed emitters for the events `{source}` declares. */");
    out.push_str("export function events(client: TrailClient) {\n");
    if decl.events.is_empty() {
        out.push_str("  return {};\n");
    } else {
        out.push_str("  return {\n");
        for (name, event) in &decl.events {
            push_event(&mut out, name, event);
        }
        out.push_str("  };\n");
    }
    out.push_str("}\n");

    out.push('\n');
    let _ = writeln!(out, "/** Typed emitters for the metrics `{source}` declares. */");
    out.push_str("export function metrics(client: TrailClient) {\n");
    if decl.metrics.is_empty() {
        out.push_str("  return {};\n");
    } else {
        out.push_str("  return {\n");
        for (name, metric) in &decl.metrics {
            push_metric(&mut out, name, metric);
        }
        out.push_str("  };\n");
    }
    out.push_str("}\n");
    out
}

fn push_props_type(out: &mut String, name: &str, event: &EventDecl) {
    let _ = writeln!(out, "{}", doc(&event.description));
    if event.props.is_empty() {
        let _ = writeln!(out, "export type {} = Record<string, never>;", props_type(name));
        return;
    }
    let _ = writeln!(out, "export type {} = {{", props_type(name));
    let required = event.props.iter().filter(|(_, p)| !p.optional);
    let optional = event.props.iter().filter(|(_, p)| p.optional);
    for (prop, kind) in required.chain(optional) {
        let mark = if kind.optional { "?" } else { "" };
        let _ = writeln!(out, "  {prop}{mark}: {};", type_of(kind));
    }
    out.push_str("};\n");
}

fn push_event(out: &mut String, name: &str, event: &EventDecl) {
    // An event whose properties are all optional can be sent with no argument.
    let default = if event.props.values().all(|p| p.optional) {
        " = {}"
    } else {
        ""
    };
    let _ = writeln!(out, "    {}", doc(&event.description));
    let _ = writeln!(
        out,
        "    {}(props: {}{default}, context?: EmitContext): void {{",
        method(name),
        props_type(name)
    );
    let _ = writeln!(
        out,
        "      client.recordEvent({}, props, context);",
        quote(name, Escape::TypeScript)
    );
    out.push_str("    },\n");
}

fn push_metric(out: &mut String, name: &str, metric: &MetricDecl) {
    let _ = writeln!(
        out,
        "    {}",
        doc(&metric_doc(&metric.description, metric.unit.as_deref()))
    );
    let (labels_param, labels_arg) = if metric.labels.is_empty() {
        (String::new(), "{}".to_string())
    } else {
        let fields: Vec<String> = metric
            .labels
            .iter()
            .map(|label| format!("{label}: string"))
            .collect();
        (
            format!(", labels: {{ {} }}", fields.join("; ")),
            "labels".to_string(),
        )
    };
    let _ = writeln!(
        out,
        "    {}(value: number{labels_param}, ts?: number): void {{",
        method(name)
    );
    let unit = match &metric.unit {
        Some(unit) => format!("unit: {}, ", quote(unit, Escape::TypeScript)),
        None => String::new(),
    };
    let _ = writeln!(
        out,
        "      client.recordMetric({}, value, {labels_arg}, {{ {unit}kind: \"{}\", ts }});",
        quote(name, Escape::TypeScript),
        metric.kind.as_str()
    );
    out.push_str("    },\n");
}
